INSERT IGNORE INTO lesson_standards (state_code, state_name, grade_level, skill, subject, standard_code, standard_title) VALUES
('AL', 'Alabama', '3-5', 'Central idea and summarizing', 'English Language Arts', 'RI.5.2', 'Determine the central idea of a text and summarize it using key supporting details, distinct from personal opinions.'),
('AL', 'Alabama', '3-5', 'Theme analysis', 'English Language Arts', 'RL.5.2', 'Determine a theme or central message of a literary text and analyze its development over the course of the text through details.'),
